def countRoutesAvoidingRectangle(m, n, r1, c1, r2, c2):
    MOD = 10 ** 9 + 7
    size = m + n
    fact = [1] * (size + 1)
    for i in range(1, size + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (size + 1)
    inv[size] = pow(fact[size], MOD - 2, MOD)
    for i in range(size, 0, -1):
        inv[i - 1] = inv[i] * i % MOD

    def ways(dr, dc):
        if dr < 0 or dc < 0:
            return 0
        return fact[dr + dc] * inv[dr] % MOD * inv[dc] % MOD

    total = ways(m - 1, n - 1)
    bad = 0
    if r1 > 0:
        for c in range(c1, c2 + 1):
            bad += ways(r1 - 1, c) * ways(m - 1 - r1, n - 1 - c)
    if c1 > 0:
        for r in range(r1, r2 + 1):
            bad += ways(r, c1 - 1) * ways(m - 1 - r, n - 1 - c1)
    return (total - bad) % MOD
